import java.util.Properties

plugins {
    alias(libs.plugins.kuma.android.application)
    alias(libs.plugins.kuma.android.hilt)
    alias(libs.plugins.kotlin.serialization)
    // Consumes the profile generated by :baselineprofile (src/release/generated/baselineProfiles).
    alias(libs.plugins.baselineprofile)
}

/**
 * Release signing. Resolved from, in order:
 *  1. `keystore.properties` in the repo root (gitignored) with keys
 *     storeFile, storePassword, keyAlias, keyPassword
 *  2. environment variables KEYSTORE_FILE, KEYSTORE_PASSWORD, KEY_ALIAS, KEY_PASSWORD (CI)
 * If neither is present the release build is unsigned (assembleRelease still works).
 */
val keystoreProperties: Properties? =
    rootProject.file("keystore.properties").takeIf { it.isFile }?.let { file ->
        Properties().apply { file.inputStream().use { load(it) } }
    }

fun signingValue(
    propertyKey: String,
    envKey: String,
): String? =
    keystoreProperties?.getProperty(propertyKey)?.takeIf { it.isNotBlank() }
        ?: providers.environmentVariable(envKey).orNull?.takeIf { it.isNotBlank() }

val releaseStoreFile = signingValue("storeFile", "KEYSTORE_FILE")
val releaseStorePassword = signingValue("storePassword", "KEYSTORE_PASSWORD")
val releaseKeyAlias = signingValue("keyAlias", "KEY_ALIAS")
val releaseKeyPassword = signingValue("keyPassword", "KEY_PASSWORD")
val hasReleaseSigning =
    listOf(releaseStoreFile, releaseStorePassword, releaseKeyAlias, releaseKeyPassword).all { it != null }

/**
 * `-PsignReleaseWithDebugKey=true` signs the release build with the debug keystore when no release key is
 * configured. Used by CI to build an installable minified APK on pull requests (catches R8 problems)
 * without any secret. Never use such an APK for distribution.
 */
val signReleaseWithDebugKey = providers.gradleProperty("signReleaseWithDebugKey").orNull == "true"

/** Single source of the app version: `VERSION_NAME` / `VERSION_CODE` in gradle.properties. */
val appVersionName: String = providers.gradleProperty("VERSION_NAME").get()
val appVersionCode: Int = providers.gradleProperty("VERSION_CODE").get().toInt()

android {
    namespace = "net.kirkanos.uptimekuma"

    defaultConfig {
        applicationId = "net.kirkanos.uptimekuma"
        versionCode = appVersionCode
        versionName = appVersionName
        vectorDrawables.useSupportLibrary = true
    }

    signingConfigs {
        if (hasReleaseSigning) {
            create("release") {
                storeFile = rootProject.file(checkNotNull(releaseStoreFile))
                storePassword = releaseStorePassword
                keyAlias = releaseKeyAlias
                keyPassword = releaseKeyPassword
                enableV1Signing = false
                enableV2Signing = true
                enableV3Signing = true
                enableV4Signing = true
            }
        }
    }

    buildTypes {
        debug {
            applicationIdSuffix = ".debug"
            versionNameSuffix = "-debug"
        }
        release {
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            signingConfig =
                when {
                    hasReleaseSigning -> signingConfigs.getByName("release")
                    signReleaseWithDebugKey -> signingConfigs.getByName("debug")
                    else -> null
                }
        }
    }

    buildFeatures {
        buildConfig = true
    }

    dependenciesInfo {
        // Keep the APK free of Google-specific dependency metadata (reproducible, F-Droid friendly).
        includeInApk = false
        includeInBundle = false
    }
}

// Android ships org.json in the framework (boot classpath wins anyway), so the copy that
// socket.io-client/engine.io-client pull in for plain JVM use is dead weight in the APK. This is the
// exclusion socket.io-client-java documents for Android. JVM unit tests keep it.
configurations.configureEach {
    if (name.endsWith("RuntimeClasspath") && !name.contains("UnitTest")) {
        exclude(group = "org.json", module = "json")
    }
}

